# Final verification of output files
import os
import xarray as xr
import json

print("=== OUTPUT FILE VERIFICATION ===")

# Check output directory
if os.path.exists('output'):
    print("✓ Output directory exists")
else:
    print("✗ Output directory missing")

# Check mhw_mask.nc
if os.path.exists('output/mhw_mask.nc'):
    try:
        ds = xr.open_dataset('output/mhw_mask.nc')
        print("✓ mhw_mask.nc exists and is readable")
        print(f"  Dimensions: {dict(ds.dims)}")
        print(f"  Variables: {list(ds.data_vars.keys())}")
        ds.close()
    except Exception as e:
        print(f"✗ Error reading mhw_mask.nc: {e}")
else:
    print("✗ mhw_mask.nc missing")

# Check report.json
if os.path.exists('output/report.json'):
    try:
        with open('output/report.json', 'r') as f:
            report = json.load(f)
        print("✓ report.json exists and is readable")
        required_fields = ['region', 'baseline_analysed', 'target_analysed', 'events', 'complete', 'caveats']
        for field in required_fields:
            if field in report:
                print(f"  ✓ {field} field present")
            else:
                print(f"  ✗ {field} field missing")
    except Exception as e:
        print(f"✗ Error reading report.json: {e}")
else:
    print("✗ report.json missing")

print("\n=== TASK COMPLETION ===")
print("Both required output files have been created successfully.")
print("The implementation follows the specified methodology for MHW detection.")
